  api.getStoryHrefs('button--primary', {
    queryParams: { args: 'label:Label', globals: 'outline:!true', custom: 'value' },
  });

  // Link to a story from an external ref
  api.getStoryHrefs('button--primary', { refId: 'external-ref' });

